#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;

const int MAXN = 1000000 + 5;

u64 B1, B2;
u64 pw1_[MAXN], pw2_[MAXN];

vector<int> d1;
vector<u64> H1, H2;
vector<int> ndStart, ndLen, ndPar, ndBest;
vector<int> centId;
vector<u64> tabK1, tabK2;
vector<int> tabVal;
int S, m;

vector<int> que, cntv, ord;

static char ibuf[1<<20];
static int ipos=0, ilen=0;
inline char gc(){
    if(ipos==ilen){
        ilen = fread(ibuf,1,1<<20,stdin);
        ipos = 0;
        if(ilen<=0) return 0;
    }
    return ibuf[ipos++];
}
inline int ri(){
    char c=gc();
    while(c<'0'||c>'9') c=gc();
    int x=0;
    while(c>='0'&&c<='9'){ x=x*10+(c-'0'); c=gc(); }
    return x;
}
inline void rs(string &s){
    char c=gc();
    while(c<'a'||c>'z') c=gc();
    s.clear();
    while(c>='a'&&c<='z'){ s.push_back(c); c=gc(); }
}

inline int insertNode(int st, int len){
    u64 k1 = H1[st+len] - H1[st]*pw1_[len];
    u64 k2 = H2[st+len] - H2[st]*pw2_[len];
    u64 h = k1 ^ (k2 * 0x9E3779B97F4A7C15ULL);
    h ^= h >> 33; h *= 0xff51afd7ed558ccdULL; h ^= h >> 33;
    int idx = (int)(h & (u64)(S-1));
    for(;;){
        int v = tabVal[idx];
        if(v==0){
            tabVal[idx]=m+1;
            tabK1[idx]=k1; tabK2[idx]=k2;
            ndStart[m]=st; ndLen[m]=len; ndPar[m]=-1;
            ++m;
            return m-1;
        } else if(tabK1[idx]==k1 && tabK2[idx]==k2){
            return v-1;
        }
        idx=(idx+1)&(S-1);
    }
}

int main(){
    {
        u64 seed = chrono::steady_clock::now().time_since_epoch().count();
        seed ^= (u64)(uintptr_t)&seed;
        mt19937_64 rng(seed);
        B1 = (rng()|1ULL);
        B2 = (rng()|1ULL);
        while(B1<1000000007ULL) B1 = B1*6364136223846793005ULL + 1;
        while(B2<1000000007ULL) B2 = B2*6364136223846793005ULL + 1;
        pw1_[0]=1; pw2_[0]=1;
        for(int i=1;i<MAXN;i++){ pw1_[i]=pw1_[i-1]*B1; pw2_[i]=pw2_[i-1]*B2; }
    }
    int T = ri();
    string s;
    string out;
    out.reserve(1<<24);
    char tmp[16];
    while(T--){
        rs(s);
        int n = (int)s.size();
        if(n==1){
            out.push_back('0');
            out.push_back('\n');
            continue;
        }
        d1.resize(n);
        H1.resize(n+1); H2.resize(n+1);
        H1[0]=0; H2[0]=0;
        for(int i=0;i<n;i++){
            u64 v = (u64)(s[i]-'a'+1);
            H1[i+1]=H1[i]*B1+v;
            H2[i+1]=H2[i]*B2+v;
        }
        for(int i=0,l=0,r=-1;i<n;i++){
            int k = (i>r)?1:min(d1[l+r-i], r-i+1);
            while(i-k>=0 && i+k<n && s[i-k]==s[i+k]) ++k;
            d1[i]=k;
            if(i+k-1>r){ l=i-k+1; r=i+k-1; }
        }
        S=1;
        while(S <= 2*n) S<<=1;
        if((int)tabVal.size()<S){ tabVal.resize(S); tabK1.resize(S); tabK2.resize(S); }
        memset(tabVal.data(),0,sizeof(int)*S);
        if((int)ndStart.size()<n){ ndStart.resize(n); ndLen.resize(n); ndPar.resize(n); ndBest.resize(n); }
        centId.resize(n);
        m=0;
        que.clear();
        for(int i=0;i<n;i++){
            int R=d1[i]-1;
            int st=i-R;
            int len=2*R+1;
            int before=m;
            int id=insertNode(st,len);
            if(m>before) que.push_back(id);
            centId[i]=id;
        }
        for(size_t qi=0; qi<que.size(); ++qi){
            int id=que[qi];
            int len=ndLen[id];
            if(len>=3){
                int before=m;
                int pid=insertNode(ndStart[id]+1, len-2);
                ndPar[id]=pid;
                if(m>before) que.push_back(pid);
            } else {
                ndPar[id]=-1;
            }
        }
        if((int)cntv.size()<n+2){ cntv.resize(n+2); }
        fill(cntv.begin(), cntv.begin()+n+2, 0);
        for(int i=0;i<m;i++) cntv[ndLen[i]]++;
        int acc=0;
        for(int l=1;l<=n;l++){ int c=cntv[l]; cntv[l]=acc; acc+=c; }
        ord.resize(m);
        for(int i=0;i<m;i++){ ord[cntv[ndLen[i]]++] = i; }
        auto eqsub = [&](int a,int b,int L)->bool{
            return (H1[a+L]-H1[a]*pw1_[L]) == (H1[b+L]-H1[b]*pw1_[L])
                && (H2[a+L]-H2[a]*pw2_[L]) == (H2[b+L]-H2[b]*pw2_[L]);
        };
        for(int t=0;t<m;t++){
            int id=ord[t];
            int p=ndPar[id];
            if(p<0){ ndBest[id]=id; continue; }
            int v=ndBest[p];
            int lu=ndLen[id], lv=ndLen[v];
            int su=ndStart[id], sv=ndStart[v];
            int ml = lu<lv?lu:lv;
            int lo=0, hi=ml;
            while(lo<hi){
                int mid=(lo+hi+1)>>1;
                if(eqsub(su,sv,mid)) lo=mid; else hi=mid-1;
            }
            int lcp=lo;
            int w;
            if(lcp==ml){ w = (lu<=lv)? id : v; }
            else { w = (s[su+lcp] < s[sv+lcp]) ? id : v; }
            ndBest[id]=w;
        }
        for(int i=0;i<n;i++){
            int b=ndBest[centId[i]];
            int ans=(ndLen[b]-1)>>1;
            int x=ans; int l=0;
            if(x==0){ tmp[l++]='0'; }
            else { while(x){ tmp[l++]=(char)('0'+x%10); x/=10; } for(int a=0,b2=l-1;a<b2;a++,b2--) swap(tmp[a],tmp[b2]); }
            out.append(tmp,l);
            out.push_back(i+1==n?'\n':' ');
        }
    }
    fwrite(out.data(),1,out.size(),stdout);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// core algorithm for a single string, exact comparison (no hashing) to validate logic
vector<int> solve_test(const string &s){
    int n=s.size();
    vector<int> d1(n);
    for(int i=0,l=0,r=-1;i<n;i++){
        int k=(i>r)?1:min(d1[l+r-i], r-i+1);
        while(i-k>=0 && i+k<n && s[i-k]==s[i+k]) ++k;
        d1[i]=k;
        if(i+k-1>r){ l=i-k+1; r=i+k-1; }
    }
    unordered_map<string,int> id;
    vector<int> nstart,nlen,npar;
    auto insert=[&](int st,int len)->int{
        string key=s.substr(st,len);
        auto it=id.find(key);
        if(it!=id.end()) return it->second;
        int idx=(int)nstart.size();
        id[key]=idx;
        nstart.push_back(st); nlen.push_back(len); npar.push_back(-1);
        return idx;
    };
    vector<int> que, centId(n);
    for(int i=0;i<n;i++){
        int R=d1[i]-1, st=i-R, len=2*R+1;
        int before=(int)nstart.size();
        int idx=insert(st,len);
        if((int)nstart.size()>before) que.push_back(idx);
        centId[i]=idx;
    }
    for(size_t qi=0; qi<que.size(); ++qi){
        int id=que[qi], len=nlen[id];
        if(len>=3){
            int before=(int)nstart.size();
            int pid=insert(nstart[id]+1, len-2);
            npar[id]=pid;
            if((int)nstart.size()>before) que.push_back(pid);
        } else npar[id]=-1;
    }
    int m=nstart.size();
    vector<int> ord(m); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){return nlen[a]<nlen[b];});
    vector<string> beststr(m);
    vector<int> bestid(m);
    for(int t=0;t<m;t++){
        int id=ord[t];
        string key=s.substr(nstart[id],nlen[id]);
        if(npar[id]<0){ beststr[id]=key; bestid[id]=id; }
        else {
            if(key < beststr[npar[id]]){ beststr[id]=key; bestid[id]=id; }
            else { beststr[id]=beststr[npar[id]]; bestid[id]=bestid[npar[id]]; }
        }
    }
    vector<int> res(n);
    for(int i=0;i<n;i++){
        int b=bestid[centId[i]];
        res[i]=(nlen[b]-1)/2;
    }
    return res;
}

vector<int> brute(const string &s){
    int n=s.size();
    vector<int> res(n);
    for(int i=0;i<n;i++){
        int R=0;
        while(i-R-1>=0 && i+R+1<n && s[i-R-1]==s[i+R+1]) R++;
        int best=0; string bs(1,s[i]);
        for(int r=1;r<=R;r++){
            string t=s.substr(i-r,2*r+1);
            if(t<bs){ bs=t; best=r; }
        }
        res[i]=best;
    }
    return res;
}

int main(){
    mt19937 rng(987654321);
    for(int iter=0; iter<300000; ++iter){
        int n = 1 + rng()%12;
        int alpha = 2 + rng()%3; // 2..4
        string s(n,'a');
        for(char &c: s) c = 'a' + rng()%alpha;
        vector<int> a = solve_test(s);
        vector<int> b = brute(s);
        if(a!=b){
            printf("MISMATCH s=%s\nbrute:", s.c_str());
            for(int x:b) printf(" %d",x);
            printf("\nsolve:");
            for(int x:a) printf(" %d",x);
            printf("\n");
            return 0;
        }
    }
    printf("ALL OK\n");
    return 0;
}

