        u64 k2=H2[st+len]-H2[st]*pw2_[len];
        u64 h=k1^(k2*0x9E3779B97F4A7C15ULL);
        h^=h>>33; h*=0xff51afd7ed558ccdULL; h^=h>>33;
        int idx=(int)(h&(u64)(S-1));
        for(;;){
            int v=tV[idx];
            if(v==0){ tV[idx]=m+1; tK1[idx]=k1; tK2[idx]=k2; nstart[m]=st; nlen[m]=len; npar[m]=-1; ++m; return m-1; }
            else if(tK1[idx]==k1 && tK2[idx]==k2) return v-1;
            idx=(idx+1)&(S-1);
        }
    };
    vector<int> que, centId(n);
    for(int i=0;i<n;i++){ int R=d1[i]-1, st=i-R, len=2*R+1; int before=m; int id=insert(st,len); if(m>before) que.push_back(id); centId[i]=id; }
    for(size_t qi=0; qi<que.size(); ++qi){
        int id=que[qi], len=nlen[id];
        if(len>=3){ int before=m; int pid=insert(nstart[id]+1,len-2); npar[id]=pid; if(m>before) que.push_back(pid); }
        else npar[id]=-1;
    }
    vector<int> cntv(n+2,0);
    for(int i=0;i<m;i++) cntv[nlen[i]]++;
    int acc=0;
    for(int l=1;l<=n;l++){ int c=cntv[l]; cntv[l]=acc; acc+=c; }
    vector<int> ord(m);
    for(int i=0;i<m;i++) ord[cntv[nlen[i]]++]=i;
    auto eqsub=[&](int a,int b,int L)->bool{
        return (H1[a+L]-H1[a]*pw1_[L])==(H1[b+L]-H1[b]*pw1_[L]) &&
               (H2[a+L]-H2[a]*pw2_[L])==(H2[b+L]-H2[b]*pw2_[L]);
    };
    for(int t=0;t<m;t++){
        int id=ord[t], p=npar[id];
        if(p<0){ nbest[id]=id; continue; }
        int v=nbest[p];
        int lu=nlen[id], lv=nlen[v], su=nstart[id], sv=nstart[v];
        int ml=min(lu,lv), lo=0, hi=ml;
        while(lo<hi){ int mid=(lo+hi+1)>>1; if(eqsub(su,sv,mid)) lo=mid; else hi=mid-1; }
        int lcp=lo, w;
        if(lcp==ml) w=(lu<=lv)?id:v;
        else w=(s[su+lcp]<s[sv+lcp])?id:v;
        nbest[id]=w;
    }
    for(int i=0;i<n;i++){ int b=nbest[centId[i]]; res[i]=(nlen[b]-1)>>1; }
    return res;
}

vector<int> brute(const string &s){
    int n=s.size(); vector<int> res(n);
    for(int i=0;i<n;i++){
        int R=0;
        while(i-R-1>=0 && i+R+1<n && s[i-R-1]==s[i+R+1]) R++;
        int best=0; string bs(1,s[i]);
        for(int r=1;r<=R;r++){ string t=s.substr(i-r,2*r+1); if(t<bs){bs=t;best=r;} }
        res[i]=best;
    }
    return res;
}

