            if(solve_full(s)!=brute(s)){ printf("MISMATCH bin n=%d s=%s\n",n,s.c_str()); return 0; }
        }
    }
    // exhaustive ternary up to length 9
    for(int n=1;n<=9;n++){
        long long tot=1; for(int i=0;i<n;i++) tot*=3;
        for(long long mask=0; mask<tot; mask++){
            long long x=mask; string s(n,'a');
            for(int i=0;i<n;i++){ s[i]='a'+(x%3); x/=3; }
            if(solve_full(s)!=brute(s)){ printf("MISMATCH ter n=%d s=%s\n",n,s.c_str()); return 0; }
        }
    }
    printf("ALL OK\n");
    return 0;
}

