    for(int i=0;i<n;i++){ int R=d1[i]-1, st=i-R, len=2*R+1; int before=m; int id=insertNode(st,len); if(m>before) que.push_back(id); centId[i]=id; }
    for(size_t qi=0;qi<que.size();++qi){ int id=que[qi],len=ndLen[id]; if(len>=3){ int before=m; int pid=insertNode(ndStart[id]+1,len-2); ndPar[id]=pid; if(m>before) que.push_back(pid);} else ndPar[id]=-1; }
