    if(m>n){ printf("!!! m>n (exceeds n+5 array bound? no, but theorem violated)\n"); }
    if((int)cntv.size()<n+5) cntv.resize(n+5);
    fill(cntv.begin(),cntv.begin()+n+5,0);
    for(int i=0;i<m;i++) cntv[ndLen[i]]++;
    int acc=0;
    for(int l=1;l<=n;l++){ int c=cntv[l]; cntv[l]=acc; acc+=c; }
    ord.resize(m);
    for(int i=0;i<m;i++) ord[cntv[ndLen[i]]++]=i;
    auto eqsub=[&](int a,int b,int L)->bool{ return (H1[a+L]-H1[a]*pw1_[L])==(H1[b+L]-H1[b]*pw1_[L]) && (H2[a+L]-H2[a]*pw2_[L])==(H2[b+L]-H2[b]*pw2_[L]); };
    for(int t=0;t<m;t++){ int id=ord[t],p=ndPar[id]; if(p<0){ndBest[id]=id;continue;} int v=ndBest[p]; int lu=ndLen[id],lv=ndLen[v],su=ndStart[id],sv=ndStart[v]; int ml=min(lu,lv),lo=0,hi=ml; while(lo<hi){int mid=(lo+hi+1)>>1; if(eqsub(su,sv,mid)) lo=mid; else hi=mid-1;} int lcp=lo,w; if(lcp==ml) w=(lu<=lv)?id:v; else w=(s[su+lcp]<s[sv+lcp])?id:v; ndBest[id]=w; }
    for(int i=0;i<n;i++){ int b=ndBest[centId[i]]; res[i]=(ndLen[b]-1)>>1; checksum+=res[i]; }
    return res;
}

