#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;
const u64 MOD = (1ULL<<61) - 1;
const int MAXN = 1000000 + 5;
u64 B1,B2,pw1_[MAXN],pw2_[MAXN];

inline u64 mulmod(u64 a,u64 b){
    __uint128_t c=(__uint128_t)a*b;
    u64 lo=(u64)c & MOD;
    u64 hi=(u64)(c>>61);
    u64 r=lo+hi;
    r=(r&MOD)+(r>>61);
    if(r>=MOD) r-=MOD;
    if(r>=MOD) r-=MOD;
    return r;
}
inline u64 addmod(u64 a,u64 b){ a+=b; if(a>=MOD) a-=MOD; return a; }
inline u64 submod(u64 a,u64 b){ return a>=b?a-b:a+MOD-b; }

vector<int> solve_full(const string &s){
    int n=s.size();
    vector<int> res(n);
    if(n==1){ res[0]=0; return res; }
    vector<int> d1(n);
    for(int i=0,l=0,r=-1;i<n;i++){
        int k=(i>r)?1:min(d1[l+r-i], r-i+1);
        while(i-k>=0 && i+k<n && s[i-k]==s[i+k]) ++k;
        d1[i]=k;
        if(i+k-1>r){ l=i-k+1; r=i+k-1; }
    }
    vector<u64> H1(n+1),H2(n+1);
    H1[0]=H2[0]=0;
    for(int i=0;i<n;i++){
        u64 v=(u64)(s[i]-'a'+1);
        H1[i+1]=addmod(mulmod(H1[i],B1),v);
        H2[i+1]=addmod(mulmod(H2[i],B2),v);
    }
    int S=1; while(S<=2*n) S<<=1;
    vector<u64> tK1(S),tK2(S); vector<int> tV(S,0);
    int m=0; vector<int> nstart(n+5),nlen(n+5),npar(n+5),nbest(n+5);
    auto insert=[&](int st,int len)->int{
        u64 k1=submod(H1[st+len], mulmod(H1[st],pw1_[len]));
        u64 k2=submod(H2[st+len], mulmod(H2[st],pw2_[len]));
        u64 h=k1^(k2*0x9E3779B97F4A7C15ULL);
        h^=h>>33; h*=0xff51afd7ed558ccdULL; h^=h>>33;
        int idx=(int)(h&(u64)(S-1));
        for(;;){ int v=tV[idx];
            if(v==0){ tV[idx]=m+1; tK1[idx]=k1; tK2[idx]=k2; nstart[m]=st; nlen[m]=len; npar[m]=-1; ++m; return m-1; }
            else if(tK1[idx]==k1&&tK2[idx]==k2) return v-1;
            idx=(idx+1)&(S-1);
        }
    };
    vector<int> que, centId(n);
    for(int i=0;i<n;i++){ int R=d1[i]-1, st=i-R, len=2*R+1; int before=m; int id=insert(st,len); if(m>before) que.push_back(id); centId[i]=id; }
    for(size_t qi=0;qi<que.size();++qi){ int id=que[qi],len=nlen[id]; if(len>=3){ int before=m; int pid=insert(nstart[id]+1,len-2); npar[id]=pid; if(m>before) que.push_back(pid);} else npar[id]=-1; }
    vector<int> cntv(n+5,0);
    for(int i=0;i<m;i++) cntv[nlen[i]]++;
    int acc=0;
    for(int l=1;l<=n;l++){ int c=cntv[l]; cntv[l]=acc; acc+=c; }
    vector<int> ord(m);
    for(int i=0;i<m;i++) ord[cntv[nlen[i]]++]=i;
    auto eqsub=[&](int a,int b,int L)->bool{
        u64 k1a=submod(H1[a+L], mulmod(H1[a],pw1_[L]));
        u64 k1b=submod(H1[b+L], mulmod(H1[b],pw1_[L]));
        if(k1a!=k1b) return false;
        u64 k2a=submod(H2[a+L], mulmod(H2[a],pw2_[L]));
        u64 k2b=submod(H2[b+L], mulmod(H2[b],pw2_[L]));
        return k2a==k2b;
    };
    for(int t=0;t<m;t++){
        int id=ord[t], p=npar[id];
        if(p<0){ nbest[id]=id; continue; }
        int v=nbest[p];
        int lu=nlen[id], lv=nlen[v], su=nstart[id], sv=nstart[v];
        int ml=min(lu,lv), lo=0, hi=ml;
        while(lo<hi){ int mid=(lo+hi+1)>>1; if(eqsub(su,sv,mid)) lo=mid; else hi=mid-1; }
        int lcp=lo,w;
        if(lcp==ml) w=(lu<=lv)?id:v; else w=(s[su+lcp]<s[sv+lcp])?id:v;
        nbest[id]=w;
    }
    for(int i=0;i<n;i++){ int b=nbest[centId[i]]; res[i]=(nlen[b]-1)>>1; }
    return res;
}

vector<int> brute(const string &s){
    int n=s.size(); vector<int> res(n);
    for(int i=0;i<n;i++){
        int R=0;
        while(i-R-1>=0 && i+R+1<n && s[i-R-1]==s[i+R+1]) R++;
        int best=0; string bs(1,s[i]);
