inline u64 mulmod(u64 a, u64 b){
    __uint128_t c = (__uint128_t)a * b;
    u64 lo = (u64)c & MOD;
    u64 hi = (u64)(c >> 61);
    u64 r = lo + hi;
    r = (r & MOD) + (r >> 61);
    if(r >= MOD) r -= MOD;
    if(r >= MOD) r -= MOD;
    return r;
}
inline u64 addmod(u64 a, u64 b){ a += b; if(a >= MOD) a -= MOD; return a; }
inline u64 submod(u64 a, u64 b){ return a >= b ? a - b : a + MOD - b; }

vector<int> d1;
vector<u64> H1, H2;
